-- Academy: rebuild Yachts Module 5 as "Inside the Brokerage": 17 pages (8 with quick checks, 9 with answerable exercises
-- saved to the Broker Portfolio) + a 7-question final quiz. Same shape as the Module 1 migration.

do $mig$
declare
  v_module uuid;
  v_q uuid;
  v_page uuid;
  rec jsonb;
  n int := 0;
  i int;
  v_pages jsonb := $json$[{"heading": "Inside the Brokerage", "body": "<p><b>What does the job really feel like?</b></p><p>So far, you have looked at the yacht world from the outside. You have learned what yachts are, how the market works, why people buy and sell, and how brokers begin understanding a client.</p><p>Now we step inside the brokerage. This is where the career becomes more real.</p><p>Because yacht brokerage is not simply: <em>Find yacht → show yacht → sell yacht.</em></p><p>A professional broker is constantly moving between people, information, opportunities and decisions. One hour you may be speaking with a prospective buyer. The next, you may be researching a yacht in another country. Then you may be reviewing market data, calling another broker, preparing a viewing, following up after a meeting, checking details with a captain, updating a client, or trying to understand why a promising opportunity has suddenly disappeared.</p><p>The work is varied. It is also demanding. And much of it happens when nobody is watching.</p><p>This module gives you a realistic view of the machinery behind the visible part of brokerage.</p>", "q": "According to this introduction, what is yacht brokerage really like?", "opts": ["A simple sequence of find, show and sell", "A constant movement between people, information, opportunities and decisions, much of it unseen", "Mostly time spent aboard yachts with clients", "A fixed office routine with little variety"], "correct": 1}, {"heading": "Chapter 1: A Broker's Working Week", "body": "<p><b>No two weeks are quite the same</b></p><p>There is no universal broker schedule. A broker's workload changes according to:</p><p>&bull; active buyers and current listings<br/>&bull; yacht movements, viewings and boat shows<br/>&bull; negotiations and transactions in progress<br/>&bull; travel and international time zones<br/>&bull; market conditions<br/>&bull; and, sometimes, pure unpredictability</p><p>A broker may spend a week preparing for a major viewing. Another week may involve almost no time aboard yachts at all. Instead, the broker might spend days communicating, researching, coordinating and following up.</p><p><b>The visible job vs the real job</b></p><p>The visible version: <em>Yachts → clients → viewings → deals.</em></p><p>The working reality: <em>Research → communication → qualification → relationship management → coordination → follow-up → negotiation → administration → judgment.</em></p><p>Both are part of the job.</p><p><b>A realistic broker day</b></p><p>&bull; <b>07:00, the world has already started.</b> Messages may have arrived overnight from clients, captains, other brokers or colleagues in different time zones. You review what needs attention.<br/>&bull; <b>08:00, market check.</b> You look at new listings, price changes, yachts sold, yachts withdrawn and relevant market activity. You are asking: <em>What has changed that matters to my clients?</em><br/>&bull; <b>09:00, client follow-up.</b> A buyer asked yesterday about three yachts. You promised to investigate one of them. Today you need the answer.<br/>&bull; <b>10:30, business development.</b> You contact a potential seller, speak with a former client, follow up with a referral or develop a relationship that may eventually produce business. There may be no immediate result. That does not make the activity unimportant.<br/>&bull; <b>12:00, yacht viewing.</b> You meet a client aboard a yacht. Now everything you have learned in Modules 1 to 4 comes together. You observe the yacht. You observe the client. You listen. You answer what you can. You record what needs verification.<br/>&bull; <b>14:00, lunch.</b> Possibly with the client, possibly with another broker, possibly at your desk.<br/>&bull; <b>15:00, transaction work.</b> An offer to coordinate, documents to review, questions from a surveyor, information to obtain from a captain or details to clarify with another broker.<br/>&bull; <b>17:00, follow-up.</b> The viewing is finished. The work is not. What did the client think? What concerns emerged? What questions remain? What should happen next?<br/>&bull; <b>19:00, international communication.</b> Depending on where clients, yachts and colleagues are located, the working day may continue. This is one reason yacht brokerage can be exciting, and why boundaries and organisation matter.</p><p><b>The broker's invisible workload</b></p><p>A great deal of brokerage happens between the major events. There are calls that produce nothing immediately. Emails that require careful wording. Information that needs checking. Clients who need patience. Deals that appear promising and then disappear. Relationships that take months or years to produce business. This is why professional consistency matters.</p><p><b>Broker's Insight</b></p><p><b>The deal is only the part of the job everyone notices. The work that creates the deal is much larger.</b></p>", "q": "What is the \"working reality\" of brokerage compared with the visible version?", "opts": ["Yachts, clients, viewings and deals only", "Mainly paperwork with little client contact", "Mostly attending boat shows and social events", "Research, communication, qualification, relationships, coordination, follow-up, negotiation, administration and judgment"], "correct": 3}, {"heading": "Exercise: Build Your Broker Week", "body": "<p><b>Try it</b></p><p>Imagine you have <b>five active clients and two yachts for sale.</b> Create a Monday to Friday schedule. Include client communication, yacht research, new business, viewings, follow-up, administration, networking, market research and personal development.</p><p>Then ask: where would you protect time for activities that may not produce immediate revenue?</p><p><b>Reflect</b></p><p>Which part of the working week sounds most interesting to you? Which sounds least attractive? That distinction matters.</p>", "exercise": {"intro": "Be realistic: five clients and two listings is a full week.", "groups": [{"title": "My broker week", "section": "profile", "fields": [{"key": "bw_mon", "label": "Monday", "type": "long", "min": 25}, {"key": "bw_tue", "label": "Tuesday", "type": "long", "min": 25}, {"key": "bw_wed", "label": "Wednesday", "type": "long", "min": 25}, {"key": "bw_thu", "label": "Thursday", "type": "long", "min": 25}, {"key": "bw_fri", "label": "Friday", "type": "long", "min": 25}]}, {"title": "Protecting the long game", "section": "profile", "fields": [{"key": "bw_protect", "label": "Where would you protect time for activities that may not produce immediate revenue?", "type": "long", "min": 40}]}, {"title": "What I noticed", "section": "profile", "fields": [{"key": "bw_like", "label": "Which part of the working week sounds most interesting to you?", "type": "long", "min": 20}, {"key": "bw_dislike", "label": "Which part sounds least attractive?", "type": "long", "min": 20}]}]}}, {"heading": "Chapter 2: Where Business Comes From", "body": "<p><b>Brokers do not simply wait for buyers to appear</b></p><p>One of the biggest misconceptions about brokerage is that the broker's job begins when a client walks through the door. In reality, professional brokers spend significant time creating the conditions for future business.</p><p>Business can come from many places:</p><p>&bull; existing clients and previous clients<br/>&bull; referrals and personal networks<br/>&bull; other brokers, captains and yacht managers<br/>&bull; shipyards, lawyers and financial professionals<br/>&bull; designers and marinas<br/>&bull; industry events and boat shows<br/>&bull; direct prospecting and company marketing<br/>&bull; digital enquiries<br/>&bull; relationships developed over time</p><p>The important point is not the list. It is the principle: <b>relationships create opportunities.</b></p><p><b>The long game</b></p><p>Imagine you meet someone today who says: <em>\"We're not ready to buy yet. Maybe in two years.\"</em> A short-term thinker may see no business. A professional broker may see the beginning of a relationship. That person may become a buyer, introduce another buyer, eventually sell a yacht, introduce a family member or become a long-term client. This is why reputation compounds.</p><p><b>Prospecting</b></p><p>Prospecting means identifying and developing potential business. It can involve researching potential owners, contacting prospective sellers, following up with previous contacts, attending industry events, asking for introductions, maintaining relationships, communicating market information and identifying people whose circumstances may have changed.</p><p>Good prospecting is not simply <em>\"Can I sell you something?\"</em> It is often: <b>\"Can I become useful to you?\"</b></p><p><b>The relationship ladder</b></p><p><em>Contact → Conversation → Understanding → Trust → Ongoing relationship → Opportunity → Business.</em></p><p>The mistake is trying to jump directly from contact to business.</p><p><b>Broker's Insight</b></p><p><b>If every conversation has to produce a transaction, people will eventually stop wanting to have conversations with you.</b></p>", "q": "Someone says, \"We're not ready to buy yet. Maybe in two years.\" How does a professional broker see this?", "opts": ["As the beginning of a relationship that may produce business later", "As a lost opportunity to be forgotten", "As a reason to pressure them to decide sooner", "As a sign they are not a serious client"], "correct": 0}, {"heading": "Exercise: The Useful Broker", "body": "<p><b>Try it</b></p><p>Imagine you have met a yacht owner who is not currently selling. Write <b>five ways you could remain useful</b> without constantly asking: <em>\"Are you ready to sell?\"</em></p><p>Think about information, introductions, market knowledge and service.</p>", "exercise": {"intro": "Useful means the owner would be glad you got in touch.", "groups": [{"title": "Five ways to stay useful", "section": "services", "fields": [{"key": "ub_1", "label": "Way 1", "type": "long", "min": 20}, {"key": "ub_2", "label": "Way 2", "type": "long", "min": 20}, {"key": "ub_3", "label": "Way 3", "type": "long", "min": 20}, {"key": "ub_4", "label": "Way 4", "type": "long", "min": 20}, {"key": "ub_5", "label": "Way 5", "type": "long", "min": 20}]}]}}, {"heading": "Chapter 3: Finding the Yacht", "body": "<p><b>The perfect yacht may not be sitting in front of you</b></p><p>Once you understand a client, the next question is: where is the right yacht? This sounds simple. It isn't.</p><p>A buyer may describe a yacht in terms of length, price and cabins. The broker needs to search more deeply. A client says: <em>\"We want around 35 metres, under €8 million, five cabins.\"</em> That describes a starting point. It does not describe the whole opportunity. You still need to investigate:</p><p>&bull; build year, refit history, condition, engine hours and maintenance<br/>&bull; stabilisation, cruising range, layout and guest experience<br/>&bull; crew accommodation and tender arrangements<br/>&bull; ownership history and charter history<br/>&bull; VAT or tax status where relevant, and registration<br/>&bull; location, availability and asking price<br/>&bull; market positioning and potential negotiation<br/>&bull; operational suitability</p><p>And some of this information may be incomplete.</p><p><b>Where brokers look</b></p><p>Depending on the market and brokerage, brokers may use yacht brokerage databases, company databases, direct broker-to-broker communication, shipyard contacts, captains and crew, management companies, industry networks, boat shows, direct owner relationships and off-market contacts.</p><p>The important distinction is between what is publicly advertised and what may exist within the broker's network.</p><p><b>Listed vs off-market</b></p><p>A yacht may be publicly marketed. Or it may be known within professional circles without being broadly advertised. An off-market conversation does not automatically mean a better opportunity. It simply means the opportunity may require stronger relationships and more careful communication.</p><p>Never assume <em>off-market = better.</em> Instead ask: <b>why is it off-market, and is it actually suitable for this client?</b></p><p><b>The broker's search process</b></p><p>&bull; <b>1. Define the client brief:</b> what are the genuine requirements?<br/>&bull; <b>2. Establish the search universe:</b> which yachts could realistically fit?<br/>&bull; <b>3. Filter:</b> remove yachts that clearly fail important requirements.<br/>&bull; <b>4. Investigate:</b> look beyond headline specifications.<br/>&bull; <b>5. Compare:</b> understand differences.<br/>&bull; <b>6. Verify:</b> identify information that needs confirmation.<br/>&bull; <b>7. Shortlist:</b> select the strongest opportunities.<br/>&bull; <b>8. Present:</b> explain why each yacht deserves attention.</p><p>This is where the broker's judgment begins to create value.</p>", "q": "What should a broker ask about an off-market yacht?", "opts": ["How quickly can I persuade the client to buy it?", "Whether it is automatically better than listed yachts", "Why is it off-market, and is it actually suitable for this client?", "Whether it is cheaper than every listed yacht"], "correct": 2}, {"heading": "Exercise: Search Without Selling", "body": "<p><b>Try it</b></p><p>Take the fictional client from Module 4: <b>James and Sophie.</b> Their broad requirements included around €8m, approximately 35m, family use, 4 to 6 weeks each summer, water sports, relaxed lunches, privacy, straightforward ownership and not overly formal.</p><p>Before looking at actual yachts, write <b>10 search criteria</b> you would use. Separate them into must have, strong preference and nice to have. Then identify two things you still do not know.</p>", "exercise": {"intro": "Criteria only. No yachts yet.", "groups": [{"title": "Search criteria for James and Sophie", "section": "yachts", "fields": [{"key": "sw_must", "label": "Must have", "type": "long", "min": 30, "placeholder": "Criteria that would rule a yacht out if missing"}, {"key": "sw_strong", "label": "Strong preference", "type": "long", "min": 30}, {"key": "sw_nice", "label": "Nice to have", "type": "long", "min": 20}, {"key": "sw_unknown", "label": "Two things you still do not know", "type": "long", "min": 30}]}]}}, {"heading": "Chapter 4: Evaluating the Opportunity", "body": "<p><b>Finding a yacht is not the same as finding the right yacht</b></p><p>A database can produce dozens of results. A broker has to decide which deserve attention. Consider two yachts:</p><p>&bull; <b>Yacht A:</b> €7.5m, 35m, five cabins, attractive photography, recently reduced asking price<br/>&bull; <b>Yacht B:</b> €7.9m, 34m, five cabins, less impressive photography, extensive recent maintenance, strong operational records, highly regarded long-term crew</p><p>Which is better? There is not enough information to answer. And that is precisely the point. A broker should resist the temptation to make decisions from headlines.</p><p><b>The opportunity assessment</b></p><p>&bull; <b>Client fit:</b> does the yacht actually suit the client's lifestyle?<br/>&bull; <b>Technical position:</b> what is known about condition, maintenance and machinery?<br/>&bull; <b>Financial position:</b> how does the asking price compare with relevant alternatives?<br/>&bull; <b>Operational reality:</b> what will ownership actually feel like?<br/>&bull; <b>Market position:</b> is the yacht competing against many similar yachts?<br/>&bull; <b>Presentation:</b> how effectively is the opportunity being marketed?<br/>&bull; <b>Risk:</b> what remains unknown?<br/>&bull; <b>Negotiation potential:</b> is there evidence that price or terms may be negotiable?</p><p><b>Facts, assumptions and questions</b></p><p>A professional broker should separate three things:</p><p>&bull; <b>FACT:</b> information that has been established<br/>&bull; <b>ASSUMPTION:</b> something you currently believe but have not confirmed<br/>&bull; <b>QUESTION:</b> something you need to investigate</p><p>This simple distinction prevents a surprising number of mistakes. For example: <em>\"The yacht has recently been refitted.\"</em> Is that a fact? Maybe. But what does \"refitted\" mean? A cosmetic refresh? A major technical refit? A partial upgrade? A complete rebuild? The broker asks: <b>what exactly was done, when, by whom, and is supporting documentation available?</b></p><p><b>Broker's Insight</b></p><p><b>A professional broker is not the person who always has the answer. It is the person who knows which answers need to be verified.</b></p>", "q": "What is an assumption, as opposed to a fact?", "opts": ["Information that has been established", "Something you need to investigate", "A statement from the seller's broker", "Something you currently believe but have not confirmed"], "correct": 3}, {"heading": "Exercise: Fact, Assumption or Question?", "body": "<p><b>Try it</b></p><p>Classify each statement as a fact, an assumption or a question. Then rewrite every assumption as a question you could investigate.</p>", "exercise": {"intro": "Decide what each statement really is, based only on what it tells you.", "groups": [{"title": "Classify the statements", "section": "yachts", "fields": [{"key": "fa_1", "label": "1. \"The yacht sleeps 10 guests.\"", "type": "choice", "options": ["Fact", "Assumption", "Question"]}, {"key": "fa_2", "label": "2. \"The yacht is probably easy to operate.\"", "type": "choice", "options": ["Fact", "Assumption", "Question"]}, {"key": "fa_3", "label": "3. \"The engines were recently serviced.\"", "type": "choice", "options": ["Fact", "Assumption", "Question"]}, {"key": "fa_4", "label": "4. \"The owner will probably accept €7 million.\"", "type": "choice", "options": ["Fact", "Assumption", "Question"]}, {"key": "fa_5", "label": "5. \"The yacht has been privately used.\"", "type": "choice", "options": ["Fact", "Assumption", "Question"]}, {"key": "fa_6", "label": "6. \"The client will love the interior.\"", "type": "choice", "options": ["Fact", "Assumption", "Question"]}, {"key": "fa_7", "label": "7. \"The yacht has good resale potential.\"", "type": "choice", "options": ["Fact", "Assumption", "Question"]}]}, {"title": "Assumptions rewritten as questions", "section": "yachts", "fields": [{"key": "fa_rewrite", "label": "Rewrite every assumption as a question you could investigate (number them to match).", "type": "long", "min": 60}]}]}}, {"heading": "Chapter 5: Working with Other Brokers", "body": "<p><b>Brokerage is a relationship business, even between competitors</b></p><p>You will rarely work in complete isolation. Other brokers may have the yacht your client wants, the client for your listing, information you need, access to an owner, local knowledge, technical contacts or transaction experience. That means professional cooperation matters.</p><p><b>Buyer broker and listing broker</b></p><p>Terminology and arrangements vary by market and transaction, but broadly: the <b>listing broker</b> represents the seller's yacht for sale. The <b>buyer's broker</b> works with the buyer to identify and evaluate suitable yachts. Sometimes the same brokerage is involved on both sides. Sometimes different brokerages cooperate. The commercial arrangements depend on the transaction and applicable agreements.</p><p>What matters for the beginner is the principle: another broker is not simply a competitor. They may also be the person who helps you complete your client's transaction.</p><p><b>Cooperation requires professionalism</b></p><p>Imagine another broker calls you about your listing: <em>\"Can you confirm whether the owner would consider a viewing on Thursday?\"</em> A poor response might be vague, delayed or dismissive. A professional response is clear: <em>\"I'll confirm with the owner and come back to you this afternoon.\"</em> Then you actually do it. That sounds basic. It isn't. <b>Reliability is remembered.</b></p><p><b>Never create unnecessary friction</b></p><p>The yacht world is relatively interconnected. The person you speak to today may later become a colleague, a source of business, a buyer's or seller's representative, a referral source, a future client or a business partner. You do not need to be everyone's best friend. You do need to be someone people can work with.</p>", "q": "Another broker asks you to confirm a viewing time with the owner. What is the professional response?", "opts": ["Give a vague answer and reply when convenient", "Say clearly you will confirm with the owner and come back to them that afternoon, then actually do it", "Ignore it, since they are a competitor", "Tell them to contact the owner directly"], "correct": 1}, {"heading": "Exercise: The Broker-to-Broker Call", "body": "<p><b>Try it</b></p><p>Another broker has a yacht that appears suitable for your client. Prepare a short call covering who you are, why you are calling, what you need to know, what you will do next and when you will follow up. Then write the call in your own words. Keep it professional and concise.</p>", "exercise": {"intro": "Five parts, then the call written out.", "groups": [{"title": "Call plan", "section": "services", "fields": [{"key": "bb_who", "label": "1. Who you are", "type": "short", "min": 10}, {"key": "bb_why", "label": "2. Why you are calling", "type": "short", "min": 15}, {"key": "bb_need", "label": "3. What you need to know", "type": "long", "min": 25}, {"key": "bb_next", "label": "4. What you will do next", "type": "short", "min": 15}, {"key": "bb_when", "label": "5. When you will follow up", "type": "short", "min": 8}]}, {"title": "The call, in my words", "section": "services", "fields": [{"key": "bb_call", "label": "Write the call as you would say it.", "type": "long", "min": 80}]}]}}, {"heading": "Chapter 6: The Broker's Toolbox", "body": "<p><b>Your tools are not just software</b></p><p>A modern broker uses technology constantly. But technology does not replace judgment. Your toolbox may include:</p><p>&bull; <b>Market databases:</b> for researching yachts, listings and market activity<br/>&bull; <b>CRM systems:</b> for recording relationships, conversations, follow-ups and opportunities<br/>&bull; <b>Email and communication tools:</b> for managing clients and relationships across time zones<br/>&bull; <b>Presentation tools:</b> for yacht comparisons, client briefs and marketing material<br/>&bull; <b>Document systems:</b> for contracts, specifications, photographs, reports and transaction documents<br/>&bull; <b>Financial and market information:</b> for pricing, ownership costs and market indicators<br/>&bull; <b>Digital calendars and task systems:</b> because a broker who forgets to follow up eventually loses opportunities</p><p><b>The most important tool</b></p><p>Your most important tool is not a database. It is your system of thinking. A good broker learns to move information through a simple process:</p><p><b>Capture → Verify → Understand → Compare → Communicate → Follow Up</b></p><p>A new yacht appears on the market. <b>Capture:</b> record the opportunity. <b>Verify:</b> check the important facts. <b>Understand:</b> determine what kind of client might suit it. <b>Compare:</b> assess it against alternatives. <b>Communicate:</b> tell the relevant client or colleague. <b>Follow up:</b> see what happens next. That final step is where many opportunities are lost.</p><p><b>The broker's CRM mindset</b></p><p>A CRM should not become a graveyard of names. It should help you remember who the person is, what they care about, what they are looking for, what you discussed, what you promised, when you should contact them, what changed and what the next action is.</p><p>The principle is simple: <b>if you cannot remember the relationship, your system should help you.</b></p>", "q": "According to the module, what is a broker's most important tool?", "opts": ["A market database", "A CRM system", "Their system of thinking: capture, verify, understand, compare, communicate and follow up", "A digital calendar"], "correct": 2}, {"heading": "Broker's Notebook: Tools and Organisation", "body": "<p><b>Broker's notebook</b></p><p>Write down the five tools you think you would personally rely on most as a broker. Then write: which part of the job would become difficult if I had poor organisation?</p>", "exercise": {"intro": "Name the tools, and say why.", "groups": [{"title": "My toolbox", "section": "profile", "fields": [{"key": "nb5_tools", "label": "The five tools I would rely on most", "type": "long", "min": 40}, {"key": "nb5_org", "label": "Which part of the job would become difficult if I had poor organisation?", "type": "long", "min": 40}]}]}}, {"heading": "Broker Challenge: The Opportunity Board", "body": "<p><b>Monday morning</b></p><p>A 34m motor yacht has just come onto the market at €7.8m. Five cabins. Mediterranean location. Private use. Attractive presentation. Recent maintenance advertised. The seller appears motivated to complete a transaction this season.</p><p>You have a client looking for approximately 35m and around €8m. You have 30 minutes.</p><p>Your task is not to sell the yacht. Instead, produce an <b>opportunity assessment.</b></p><p>&bull; <b>Part 1, what do you know?</b> List the facts provided.<br/>&bull; <b>Part 2, what do you not know?</b> List at least 10 questions.<br/>&bull; <b>Part 3, what could make it suitable?</b> Identify the potential points of fit.<br/>&bull; <b>Part 4, what could make it unsuitable?</b> Identify potential concerns.<br/>&bull; <b>Part 5, what would you verify first?</b> Choose your five highest-priority questions.<br/>&bull; <b>Part 6, what happens next?</b> Write a short professional message to the client explaining that you have identified a yacht that may be worth considering.</p><p>Do not oversell it. Do not call it \"perfect.\" Your objective is to create a reason for the client to investigate further.</p>", "exercise": {"intro": "Assessment first. Sales pitch never.", "groups": [{"title": "The opportunity assessment", "section": "yachts", "fields": [{"key": "ob_know", "label": "Part 1: What do you know? (facts only)", "type": "long", "min": 40}, {"key": "ob_dont", "label": "Part 2: What do you not know? At least 10 questions.", "type": "long", "min": 100}, {"key": "ob_fit", "label": "Part 3: What could make it suitable?", "type": "long", "min": 40}, {"key": "ob_unfit", "label": "Part 4: What could make it unsuitable?", "type": "long", "min": 40}, {"key": "ob_first", "label": "Part 5: The five questions you would verify first", "type": "long", "min": 60}]}, {"title": "Message to the client", "section": "services", "fields": [{"key": "ob_msg", "label": "Part 6: A short professional message. Do not oversell it, and do not call it \"perfect\".", "type": "long", "min": 80}]}]}}, {"heading": "Professional Output: My Brokerage Opportunity Assessment", "body": "<p><b>My Brokerage Opportunity Assessment</b></p><p>Create a one-page document on a real or fictional opportunity. This becomes another page of your Broker Portfolio.</p>", "exercise": {"intro": "One page. Someone else should be able to act on it.", "groups": [{"title": "Opportunity assessment", "section": "yachts", "fields": [{"key": "oa_client", "label": "1. Client: who are you representing?", "type": "long", "min": 20}, {"key": "oa_opp", "label": "2. Opportunity: what yacht or opportunity are you evaluating?", "type": "long", "min": 20}, {"key": "oa_fit", "label": "3. Client fit: why might it suit them?", "type": "long", "min": 30}, {"key": "oa_conc", "label": "4. Concerns: what could make it unsuitable?", "type": "long", "min": 30}, {"key": "oa_facts", "label": "5. Facts: what do you know?", "type": "long", "min": 30}, {"key": "oa_unk", "label": "6. Unknowns: what needs verification?", "type": "long", "min": 30}, {"key": "oa_pri", "label": "7. Priority questions: what five questions matter most?", "type": "long", "min": 40}, {"key": "oa_next", "label": "8. Next action: what should happen next?", "type": "long", "min": 20}, {"key": "oa_follow", "label": "9. Follow-up: who needs to be contacted, and when?", "type": "long", "min": 20}]}]}}, {"heading": "Reflection: What Appeals to Me?", "body": "<p><b>Reflection</b></p><p>Some of this work happens aboard yachts. Much of it does not. It involves finding opportunities, researching information, building relationships, following up, evaluating uncertainty, communicating professionally, cooperating with other brokers, organising information and making judgments. These are useful signals as you continue.</p>", "exercise": {"intro": "Answer honestly. There are no right answers.", "groups": [{"title": "My signals", "section": "profile", "fields": [{"key": "rf5_appeal", "label": "What part of this work appeals to me?", "type": "long", "min": 20}, {"key": "rf5_struggle", "label": "What part would I struggle with?", "type": "long", "min": 20}, {"key": "rf5_research", "label": "Do I enjoy researching and comparing opportunities?", "type": "short", "min": 10}, {"key": "rf5_rel", "label": "Do I enjoy building professional relationships?", "type": "short", "min": 10}, {"key": "rf5_uncert", "label": "Am I comfortable with uncertainty?", "type": "short", "min": 10}, {"key": "rf5_org", "label": "Can I stay organised when several things are happening at once?", "type": "short", "min": 10}, {"key": "rf5_follow", "label": "Do I naturally follow through on commitments?", "type": "short", "min": 10}]}]}}, {"heading": "Final Reflection and What Comes Next", "body": "<p><b>Module 5: final reflection</b></p><p>You have now moved another step closer to the real work. You understand the yacht. You understand the market. You understand the client. Now you are beginning to understand how a broker connects all three. That connection is where brokerage starts becoming a profession.</p><p><b>Broker's notebook, Module 5</b></p><p>By the end of this module, you should be able to explain:</p><p>&bull; what a broker's working week can look like<br/>&bull; where brokerage business can come from<br/>&bull; how brokers search for yachts<br/>&bull; why finding a yacht is not the same as finding the right yacht<br/>&bull; the difference between facts, assumptions and questions<br/>&bull; why broker-to-broker relationships matter<br/>&bull; what a broker's professional toolbox looks like<br/>&bull; why follow-up and organisation are commercially important</p><p><b>What comes next</b></p><p>Knowing how the business works is not the same as knowing how a transaction actually unfolds. Soon, you will move from the brokerage environment into the deal itself. You will follow a yacht from <em>client → search → viewing → offer → survey → negotiation → closing.</em> And you will discover where the pressure, uncertainty and judgment really appear.</p><p><b>Module 6: The Art of the Deal.</b> <em>How does a yacht actually get sold?</em> You will follow the transaction from the first serious client conversation through viewing, offer, survey, sea trial, negotiation, closing and delivery. The yacht is no longer simply an object. It becomes a transaction. And the broker becomes the person helping everyone move through it.</p>", "q": "What does the next module, The Art of the Deal, follow?", "opts": ["A yacht transaction from first serious conversation through viewing, offer, survey, negotiation, closing and delivery", "Only the marketing of a yacht listing", "The daily routine of a broker's assistant", "How yachts are built at the shipyard"], "correct": 0}]$json$;
  v_final jsonb := $json$[{"q": "Is a broker's job primarily about showing yachts?", "opts": ["Yes, showing yachts is the core of the job", "Yes, everything else is administration", "No. Viewings are one part of a much larger process involving research, communication, qualification, relationships, negotiation, coordination and follow-up", "No, it is primarily about setting the asking price"], "correct": 2}, {"q": "Why can an \"off-market\" yacht be difficult to evaluate?", "opts": ["Information may be less publicly available and access may depend on relationships; off-market does not automatically mean better", "Because off-market yachts are always overpriced", "Because off-market yachts are always cheaper", "Because they cannot legally be sold"], "correct": 0}, {"q": "What is the difference between a fact and an assumption?", "opts": ["A fact is what the seller says; an assumption is what the buyer says", "A fact is a price; an assumption is a specification", "There is no real difference", "A fact has been established; an assumption is something you believe but have not verified"], "correct": 3}, {"q": "Why are other brokers important?", "opts": ["They are only competitors to be avoided", "They may control relevant listings, represent buyers, provide information, introduce opportunities or cooperate on a transaction", "They set the market prices", "They handle a broker's paperwork"], "correct": 1}, {"q": "What is prospecting?", "opts": ["Inspecting a yacht before a survey", "Negotiating the price of a yacht", "Writing the yacht's listing", "Identifying and developing potential future business and relationships"], "correct": 3}, {"q": "What is the purpose of a CRM?", "opts": ["To replace a broker's judgment", "To list yachts publicly", "To organise relationships, information, commitments and follow-up so opportunities and important details are not lost", "To calculate commission"], "correct": 2}, {"q": "What is one of the broker's most important habits?", "opts": ["Rapid discounting", "Consistent follow-up", "Avoiding other brokers", "Talking about yachts as much as possible"], "correct": 1}]$json$;
begin
  select id into v_module from public.academy_modules where track = 'yachts' and module_number = 5;
  if v_module is null then
    raise exception 'Yachts module 5 not found';
  end if;

  update public.academy_modules
     set title = 'Inside the Brokerage', description = 'What does the job really feel like?'
   where id = v_module;

  delete from public.academy_module_pages where module_id = v_module;
  delete from public.academy_quiz_questions where module_id = v_module;

  for rec in select * from jsonb_array_elements(v_pages) loop
    n := n + 1;
    if rec ? 'exercise' then
      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id, exercise)
      values (v_module, n, rec->>'heading', rec->>'body', null, rec->'exercise');
    else
      insert into public.academy_quiz_questions (module_id, question_text, order_index, stage, page_number)
      values (v_module, rec->>'q', 0, 'checkpoint', n)
      returning id into v_q;

      for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
        insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
        values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
      end loop;

      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id)
      values (v_module, n, rec->>'heading', rec->>'body', v_q);
    end if;
  end loop;

  n := 0;
  for rec in select * from jsonb_array_elements(v_final) loop
    n := n + 1;
    insert into public.academy_quiz_questions (module_id, question_text, order_index, stage)
    values (v_module, rec->>'q', n - 1, 'final')
    returning id into v_q;

    for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
      insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
      values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
    end loop;
  end loop;
end
$mig$;
